using System.Buffers;
using MessagePack;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class Str8HeaderAndDuplicateKeyTests
{
    [Fact]
    public void StringHeaderFor40BytesUsesStr8()
    {
        var buffer = new ArrayBufferWriter<byte>();
        var writer = new MessagePackWriter(buffer);
        writer.WriteStringHeader(40);
        writer.Flush();
        byte[] bytes = buffer.WrittenSpan.ToArray();
        Assert.Equal(2, bytes.Length);
        Assert.Equal((byte)0xD9, bytes[0]);
        Assert.Equal((byte)40, bytes[1]);
    }

    [Fact]
    public async Task DuplicateIntKeyIsNotSilentlyDropped()
    {
        string source = """
            using MessagePack;

            namespace Sample
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [MessagePackObject]
                public class MyObject
                {
                    [Key(0)]
                    public int FirstValue { get; set; }

                    [Key(0)]
                    public int SecondValue { get; set; }
                }
            }
            """;

        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var refs = new List<MetadataReference>(frameworkRefs);
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        var compilation = CSharpCompilation.Create(
            "ReceiptsDupKey",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out var diagnostics);
        var result = driver.GetRunResult();

        string generated = string.Join("\n", result.GeneratedTrees.Select(t => t.ToString()));
        bool anyReported = diagnostics.Any(d => d.Severity >= DiagnosticSeverity.Warning)
            || result.Diagnostics.Any(d => d.Severity >= DiagnosticSeverity.Warning);
        bool silentlyDropped = generated.Contains("FirstValue") && !generated.Contains("SecondValue");

        Assert.False(silentlyDropped && !anyReported, "Generated formatter silently dropped SecondValue (duplicate Key(0)) without any diagnostic.");
    }
}
